{"implementation":"def solve(case):
    import json
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    # build maps
    node_map = {n['id']: n for n in nodes}
    children_of = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children_of.setdefault(pid, []).append(n['id'])
    # initial retained set
    retained = set(node_map.keys())
    # candidate nodes: removable and not root (root is not removable anyway)
    candidates = []
    for n in nodes:
        if n['removable']:
            candidates.append(n)
    # sort by depth descending, then id ascending
    candidates.sort(key=lambda x: (-x['depth'], x['id']))
    removed_order = []
    for node in candidates:
        nid = node['id']
        if nid not in retained:
            continue
        # check retained children
        has_retained_child = any(
            child_id in retained
            for child_id in children_of.get(nid, [])
        )
        if has_retained_child:
            continue
        # check if removing would lose a required symbol
        symbol = node['symbol']
        # count occurrences of this symbol in retained (before removal)
        count = sum(1 for rid in retained if node_map[rid]['symbol'] == symbol)
        # also directly check each required symbol
        ok = True
        for req_sym in required_symbols:
            # count occurrences in retained excluding this node
            occ = sum(1 for rid in retained if node_map[rid]['symbol'] == req_sym)
            if nid in retained and node_map[nid]['symbol'] == req_sym:
                occ -= 1
            if occ == 0:
                ok = False
                break
        if not ok:
            continue
        # remove
        retained.discard(nid)
        removed_order.append(nid)
    # sort retained ids
    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained_sorted
    }
